from pathlib import Path
import subprocess,re,json
root=Path('cards_mse/01_pre_alpha/01_legend_of_alpha/01_YGO_Legend_of_Alpha.mse-set')
names=subprocess.check_output(['git','diff','--name-only','--',str(root),'cards_mse/01_pre_alpha/stage.json'],text=True).splitlines()
# complete reads utf8sig
for n in names: Path(n).read_text(encoding='utf-8-sig')
print('complete_reads',len(names))
settxt=(root/'set').read_text(encoding='utf-8-sig'); inc=re.findall(r'^include_file: (.+)$',settxt,re.M)
cards=[p.name for p in root.glob('card *')]
print('includes',len(inc),'cards',len(cards),'dups',len(inc)-len(set(inc)),'missing',set(inc)-set(cards),'orphan cards',set(cards)-set(inc))
refs=[]; bad=[]; codes=[]
for x in inc:
 t=(root/x).read_text(encoding='utf-8-sig')
 for m in re.finditer(r'^\t(?:image|mainframe_image|mainframe_image_2):\s*(.*)$',t,re.M):
  if m.group(1):
   refs.append(m.group(1));
   if not (root/m.group(1)).is_file(): bad.append((x,m.group(1)))
 for m in re.finditer(r'^\tcard_code_text(?:_2|_3)?:\s*(\d+)/(\d+)\s',t,re.M): codes.append((x,*m.groups()))
print('image refs',len(refs),'unique',len(set(refs)),'bad',bad)
imgs={p.relative_to(root).as_posix() for p in (root/'mse_images').iterdir() if p.is_file()}; print('orphan images',sorted(imgs-set(refs)))
print('code total values',sorted(set(y[2] for y in codes)),'code entries',len(codes),'bad indexes',[(x,a,b) for x,a,b in codes if int(a)<1 or int(a)>len(inc) or int(b)!=len(inc)][:10])
print('BOM changed',sum(Path(n).read_bytes().startswith(b'\xef\xbb\xbf') for n in names if Path(n).name.startswith('card ')))
